<?php get_header(); ?><section class="rrv-content"><div class="rrv-container"><div class="rrv-heading"><h1><?php echo is_home()?'Journal':esc_html(get_the_archive_title());?></h1></div><div class="rrv-grid"><?php if(have_posts()):while(have_posts()):the_post();?><article class="rrv-card"><?php if(has_post_thumbnail()):?><a class="rrv-card__media" href="<?php the_permalink();?>"><?php the_post_thumbnail('large');?></a><?php endif;?><div class="rrv-card__body"><h3><a href="<?php the_permalink();?>"><?php the_title();?></a></h3><p><?php echo esc_html(get_the_excerpt());?></p><a class="rrv-btn" href="<?php the_permalink();?>">Read more</a></div></article><?php endwhile;else:?><p>No content found.</p><?php endif;?></div><div style="margin-top:35px"><?php the_posts_pagination();?></div></div></section><?php get_footer(); ?>